import MoodOutlined from '@mui/icons-material/MoodOutlined'
import { IconButton, Popover, Tooltip } from '@mui/material'
import { activeEditor$, useCellValue } from '@mdxeditor/editor'
import { useState, type MouseEvent } from 'react'
import { MarkdownEmojiPickerContent } from './markdown_emoji_picker_content'

interface MarkdownEmojiToolbarControlProps {
    overlayContainer?: HTMLElement | null
}

/** Toolbar popover that inserts a Unicode emoji character at the active selection. */
export function MarkdownEmojiToolbarControl(props: MarkdownEmojiToolbarControlProps) {
    const { overlayContainer } = props
    const activeEditor = useCellValue(activeEditor$)
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    return (
        <>
            <Tooltip title="Insert emoji">
                <span>
                    <IconButton
                        aria-controls={anchorElement ? 'markdown-emoji-picker' : undefined}
                        aria-expanded={!!anchorElement}
                        aria-haspopup="dialog"
                        aria-label="Insert emoji"
                        disabled={!activeEditor}
                        onClick={handleOpen}
                        size="small"
                    >
                        <MoodOutlined fontSize="small" />
                    </IconButton>
                </span>
            </Tooltip>
            <Popover
                anchorEl={anchorElement}
                anchorOrigin={{ horizontal: 'left', vertical: 'bottom' }}
                container={overlayContainer ?? undefined}
                id="markdown-emoji-picker"
                onClose={handleClose}
                open={!!anchorElement}
                slotProps={{ paper: { 'aria-label': 'Emoji picker', role: 'dialog' } }}
            >
                {anchorElement ? <MarkdownEmojiPickerContent activeEditor={activeEditor} onClose={handleClose} /> : null}
            </Popover>
        </>
    )
}

import { Box, IconButton, Popover, Stack, Tooltip, Typography } from '@mui/material'
import SourceCommit from 'mdi-material-ui/SourceCommit'
import type { MouseEvent } from 'react'
import { useState } from 'react'
import type { CommitReference } from '../../../../data/electron_action_bridge'
import { CommitReferenceRow } from '../../conversation/commit_reference_row'

interface ActionCommitDropdownProps {
    commits: CommitReference[]
}

/** Toolbar dropdown listing every commit produced by the action's runs. */
export function ActionCommitDropdown(props: ActionCommitDropdownProps) {
    const { commits } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const handleOpen = (event: MouseEvent<HTMLElement>) => setAnchorElement(event.currentTarget)
    const handleClose = () => setAnchorElement(null)

    if (commits.length === 0) return null

    return (
        <>
            <Tooltip title="Commit history">
                <IconButton aria-label="Commit history" onClick={handleOpen} size="small" sx={{ height: 26, width: 26 }}>
                    <SourceCommit sx={{ fontSize: 16 }} />
                </IconButton>
            </Tooltip>
            <Popover
                anchorEl={anchorElement}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
                onClose={handleClose}
                open={!!anchorElement}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            >
                <Box sx={{ maxHeight: 360, maxWidth: 560, minWidth: 320, overflow: 'auto', px: 1.5, py: 1 }}>
                    <Typography color="text.secondary" sx={{ fontSize: 12, fontWeight: 600 }} variant="caption">
                        Commits
                    </Typography>
                    <Stack spacing={0.5}>
                        {commits.map((commitReference) => (
                            <CommitReferenceRow
                                commitReference={commitReference}
                                key={`${commitReference.repositoryRoot}-${commitReference.commit}`}
                            />
                        ))}
                    </Stack>
                </Box>
            </Popover>
        </>
    )
}

import { Dialog, Popover } from '@mui/material'
import type { ReactNode } from 'react'

interface StatusDetailsSurfaceProps {
    anchorElement: HTMLElement | null
    children: ReactNode
    labelId: string
    mobile: boolean
    onClose: () => void
}

/** Uses existing desktop popover placement and a viewport-safe dialog on mobile. */
export function StatusDetailsSurface(props: StatusDetailsSurfaceProps) {
    const { anchorElement, children, labelId, mobile, onClose } = props

    if (mobile) {
        return (
            <Dialog
                aria-labelledby={labelId}
                fullWidth
                maxWidth="xs"
                onClose={onClose}
                open={!!anchorElement}
                slotProps={{ paper: { sx: { m: 1, maxHeight: 'calc(100vh - 16px)', maxWidth: 'calc(100vw - 16px)' } } }}
            >
                {children}
            </Dialog>
        )
    }

    return (
        <Popover
            anchorEl={anchorElement}
            anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
            onClose={onClose}
            open={!!anchorElement}
            transformOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        >
            {children}
        </Popover>
    )
}

